      SUBROUTINE BPRINT      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'CCENT.CIN'      INCLUDE 'CONSTS.CIN'      INCLUDE 'ELM0B.CIN'      INCLUDE 'ELM4A.CIN'      INCLUDE 'ELM5A.CIN'      INCLUDE 'ELM13A.CIN'      INCLUDE 'ELM13B.CIN'      INCLUDE 'ELM15B.CIN'      INCLUDE 'ELM15C.CIN'      INCLUDE 'ELM20.CIN'      INCLUDE 'IOUNIT.CIN'      INCLUDE 'OC.CIN'      INCLUDE 'XYZOLD.CIN'C      DIMENSION     OBEG(3,3), OCEN(3,3), OEND(3,3), OFOO(3,3),      1              OROT(3,3), OTEMP(3,3)      DIMENSION     XBEG(3), XEND(3)C      IF (ONLY) GO TO 100CC     TRANSFORMATION AT END OF ELEMENTC      DO 28 J = 1, 3      DO 28 K = 1, 3      OBEG(J,K) = OOLD(J,K)   28 CONTINUE      XBEG(1) = XOLD      XBEG(2) = YOLD      XBEG(3) = ZOLDC      DO 30 J = 1, 3      DO 30 K = 1, 3      OEND(J,K) = O(4,J,K)   30 CONTINUE      XEND(1) = X0(4,1)      XEND(2) = X0(4,2)      XEND(3) = X0(4,3)CC     LOOK FOR TILT OR REFERC      IF (REFER .AND. TOTRC .NE. 0.0) THEN        TOTR = TOTRC        IF (.NOT. REFER) TOTR = TOTR - TOTROT        COST = COS(TOTR)        SINT = SIN(TOTR)        OROT(1,1) = COST        OROT(1,2) = SINT        OROT(1,3) = 0.0        OROT(2,1) = - SINT        OROT(2,2) = COST        OROT(2,3) = 0.0        OROT(3,1) = 0.0        OROT(3,2) = 0.0        OROT(3,3) = 1.0      ENDIFC      AL2 = 0.5*AL      CS2 = COS(AL2)      SN2 = SIN(AL2)      OFOO(1,1) = CS2      OFOO(1,2) = 0.0      OFOO(1,3) = SN2      OFOO(2,1) = 0.0      OFOO(2,2) = 1.0      OFOO(2,3) = 0.0      OFOO(3,1) = - SN2      OFOO(3,2) = 0.0      OFOO(3,3) = CS2CC     TRANSFORMATION OF ORIENTATION OF CENTER OF MAGNETC      IF (REFER .AND. TOTRC .NE. 0.0) THEN        DO 55 J = 1, 3        DO 55 K = 1, 3        BLOB = 0.0        DO 54 M = 1, 3        BLOB = BLOB + OFOO(J,M)*OROT(M,K)   54   CONTINUE        OTEMP(J,K) = BLOB   55   CONTINUEC        DO 60 J = 1, 3        DO 60 K = 1, 3        BLOB = 0.0        DO 59 M = 1, 3        BLOB = BLOB + OROT(M,J)*OTEMP(M,K)   59   CONTINUE        OFOO(J,K) = BLOB   60   CONTINUE      ENDIFC      DO 80 J = 1, 3      DO 80 K = 1, 3      BLOB = 0.0      DO 78 M = 1, 3      BLOB = BLOB + OFOO(M,J)*OEND(M,K)   78 CONTINUE      OTEMP(J,K) = BLOB   80 CONTINUEC         DO 85 J = 1, 3      DO 85 K = 1, 3      OCEN(J,K) = OTEMP(J,K)   85 CONTINUECC     CALCULATE COORDINATES AT CENTER OF MAGNETC      SUMC = 0.0      SUMO = 0.0      DO 95 J = 1, 3      CDIF = XEND(J) - XBEG(J)      OSUM = OEND(3,J) + OBEG(J,3)      SUMC = SUMC + CDIF*OSUM      SUMO = SUMO + OSUM**2   95 CONTINUE      SEFF = SUMC/SUMO         XCEN = XBEG(1) + OBEG(3,1)*SEFF      YCEN = XBEG(2) + OBEG(3,2)*SEFF      ZCEN = XBEG(3) + OBEG(3,3)*SEFF  CC     PRINT COORDINATES AT CENTER OF MAGNETC      ALONG = (LC - 0.5*LMAG)/UFLOOR(1)      XCENT = XCEN/UFLOOR(1)      YCENT = YCEN/UFLOOR(1)      ZCENT = ZCEN/UFLOOR(1)C      CSY = OCEN(3,3)      SNY = OCEN(3,1)      IF (CSY .EQ. 0.0) THEN        IF (SNY .GT. 0.0) YAW = 0.5*PI        IF (SNY .LT. 0.0) YAW = - 0.5*PI      ELSE        YAW = ATAN(SNY/CSY)        IF (CSY .LT. 0.0) THEN          SHIFT = SIGN(PI,SNY)          YAW = YAW + SHIFT        ENDIF        YAW = YAW/UFLOOR(2)      ENDIFC      PITCH = ASIN(OCEN(3,2))/UFLOOR(2)C      IF (OCEN(2,2) .NE. 0.0) ROLL = ATAN(OCEN(1,2)/OCEN(2,2))      IF (OCEN(2,2) .EQ. 0.0 .AND. OCEN(1,2) .GT. 0.0) ROLL = 0.5*PI      IF (OCEN(2,2) .EQ. 0.0 .AND. OCEN(1,2) .LT. 0.0) ROLL = - 0.5*PI      IF (OCEN(2,2) .LT. 0.0) THEN        SHIFT = SIGN(PI,OCEN(1,2))        ROLL = ROLL + SHIFT      ENDIF      ROLL = ROLL/UFLOOR(2)C      IF (UFLOOR(2) .LE. 0.1) THEN        WRITE (NOUT,1000) ALONG, XFLOOR(1), XCENT, YCENT, ZCENT,      1                    XFLOOR(1), YAW, PITCH, ROLL, XFLOOR(2)      ELSE        WRITE (NOUT,1001) ALONG, XFLOOR(1), XCENT, YCENT, ZCENT,     1                    XFLOOR(1), YAW, PITCH, ROLL, XFLOOR(2)      ENDIFC 1000 FORMAT (1H ,8X,F10.3,1X,A4,9X,3F11.4,1X,A4,1X,3F10.3,1X,A4) 1001 FORMAT (1H ,5X,F15.6,1X,A4,8X,3F13.5,1X,A4,1X,3F12.6,1X,A4)  100 RETURN      END